export function composerLines(input: { count: number }): string {
  const count = formatNumber(input.count);
  switch (currentLanguage()) {
    case "ar":
      switch (pluralCategory(input.count)) {
        case "zero":
          return `${count} سطر`;
        case "one":
          return `${count} سطر`;
        case "two":
          return `${count} سطران`;
        case "few":
          return `${count} أسطر`;
        case "many":
          return `${count} سطرًا`;
        default:
          return `${count} سطر`;
      }
    case "de":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${count} Zeile`;
        default:
          return `${count} Zeilen`;
      }
    case "es":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${count} línea`;
        case "many":
          return `${count} de líneas`;
        default:
          return `${count} líneas`;
      }
    case "fr":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${count} ligne`;
        case "many":
          return `${count} lignes`;
        default:
          return `${count} lignes`;
      }
    case "ja":
      switch (pluralCategory(input.count)) {
        default:
          return `${count}行`;
      }
    case "ko":
      switch (pluralCategory(input.count)) {
        default:
          return `${count}줄`;
      }
    case "pt-BR":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${count} linha`;
        case "many":
          return `${count} linhas`;
        default:
          return `${count} linhas`;
      }
    case "zh-Hans":
      switch (pluralCategory(input.count)) {
        default:
          return `${count} 行`;
      }
    case "zh-Hant":
      switch (pluralCategory(input.count)) {
        default:
          return `${count} 行`;
      }
    case "en-XA":
      switch (pluralCategory(input.count, "en")) {
        case "one":
          return `[${count} ļîñé ~~]`;
        default:
          return `[${count} ļîñéš ~~]`;
      }
    case "ar-XB":
      switch (pluralCategory(input.count, "en")) {
        case "one":
          return `${count}\u202e line\u202c`;
        default:
          return `${count}\u202e lines\u202c`;
      }
  }
  switch (pluralCategory(input.count)) {
    case "one":
      return `${count} line`;
    default:
      return `${count} lines`;
  }
}

