export function uiCardStackNew(input: { count: number }): string {
  const count = formatNumber(input.count);
  switch (currentLanguage()) {
    case "ar":
      switch (pluralCategory(input.count)) {
        case "zero":
          return `${count} جديدة`;
        case "one":
          return `${count} جديدة`;
        case "two":
          return `${count} جديدتان`;
        case "few":
          return `${count} جديدة`;
        case "many":
          return `${count} جديدة`;
        default:
          return `${count} جديدة`;
      }
    case "de":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${count} neu`;
        default:
          return `${count} neu`;
      }
    case "es":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${count} nueva`;
        case "many":
          return `${count} nuevas`;
        default:
          return `${count} nuevas`;
      }
    case "fr":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${count} nouvelle`;
        case "many":
          return `${count} nouvelles`;
        default:
          return `${count} nouvelles`;
      }
    case "ja":
      switch (pluralCategory(input.count)) {
        default:
          return `${count}件の新着`;
      }
    case "ko":
      switch (pluralCategory(input.count)) {
        default:
          return `새 카드 ${count}개`;
      }
    case "pt-BR":
      switch (pluralCategory(input.count)) {
        case "one":
          return `${count} novo`;
        case "many":
          return `${count} novos`;
        default:
          return `${count} novos`;
      }
    case "zh-Hans":
      switch (pluralCategory(input.count)) {
        default:
          return `${count} 张新卡片`;
      }
    case "zh-Hant":
      switch (pluralCategory(input.count)) {
        default:
          return `${count} 張新的`;
      }
    case "en-XA":
      switch (pluralCategory(input.count, "en")) {
        case "one":
          return `[${count} ñéŵ ~~]`;
        default:
          return `[${count} ñéŵ ~~]`;
      }
    case "ar-XB":
      switch (pluralCategory(input.count, "en")) {
        case "one":
          return `${count}\u202e new\u202c`;
        default:
          return `${count}\u202e new\u202c`;
      }
  }
  switch (pluralCategory(input.count)) {
    case "one":
      return `${count} new`;
    default:
      return `${count} new`;
  }
}

